import json,re
e=json.load(open('/var/folders/cr/t3l2xddj6x77vp_7482n4jkm0000gn/T/proofreader-ci-20261116-q77fe48m/1/envelope.json'))
ratios={'trim-the-fat':(.90,.95),'less-wordy':(.70,.70),'more-concise':(.60,.60),'more-succinct':(.40,.50),'shorten-markdown-changes-quotes':(.70,.70)}
for c in e['cases']:
 if c['id'] in ratios:
  p=c['prompt'].removeprefix(e['runner_context']).lstrip()
  s=p.split('Source:\n',1)[1] if 'Source:\n' in p else p.split(': ',1)[1]
  words=[w for w in s.split() if not re.fullmatch(('['+chr(96)+'~*_#|>\\-]+'),w)]
  n=len(words)
  print(json.dumps({'id':c['id'],'source':s,'N':n,'budget':[round(n*r) for r in ratios[c['id']]],'convention':'Whitespace-separated units, excluding standalone fence/markup delimiters'}))

